-- ===========================================================================
-- Nexgile WealthAgent — Supabase / PostgreSQL schema
--
-- Generated from the SQLAlchemy models in backend/app/models so this file and
-- the ORM cannot drift apart. Regenerate with:
--
--     python -m app.seeds.emit_schema        (from backend/)
--
-- Apply it in the Supabase SQL editor, or:
--     psql "$DATABASE_URL" -f supabase/schema.sql
--
-- Then load the demonstration dataset:
--     DATABASE_URL="postgresql://..." python seed.py
--
-- Conventions
--   * Primary keys are UUID strings generated by the application.
--   * Every table carries created_at / updated_at.
--   * Foreign keys use ON DELETE CASCADE for owned records and SET NULL for
--     references that should survive the parent being removed.
--   * Indexes back every foreign key and every column the API filters on.
-- ===========================================================================

BEGIN;

CREATE TABLE benchmarks (
	code VARCHAR(32) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	description TEXT, 
	composition JSON NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);

CREATE TABLE charities (
	name VARCHAR(160) NOT NULL, 
	ein_masked VARCHAR(24), 
	mission_area VARCHAR(80) NOT NULL, 
	location VARCHAR(120), 
	rating FLOAT, 
	is_qualified BOOLEAN NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE custodians (
	name VARCHAR(120) NOT NULL, 
	short_name VARCHAR(48) NOT NULL, 
	connection_type VARCHAR(32) NOT NULL, 
	feed_status VARCHAR(24) NOT NULL, 
	logo_hint VARCHAR(32), 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE education_content (
	title VARCHAR(200) NOT NULL, 
	content_type VARCHAR(32) NOT NULL, 
	learning_path VARCHAR(96) NOT NULL, 
	level VARCHAR(24) NOT NULL, 
	duration_minutes INTEGER NOT NULL, 
	summary TEXT NOT NULL, 
	body TEXT, 
	tags JSON NOT NULL, 
	published_on DATE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE permissions (
	key VARCHAR(64) NOT NULL, 
	description TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_permissions_key ON permissions (key);

CREATE TABLE roles (
	key VARCHAR(48) NOT NULL, 
	label VARCHAR(96) NOT NULL, 
	description TEXT, 
	home_route VARCHAR(96) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_roles_key ON roles (key);

CREATE TABLE securities (
	symbol VARCHAR(24) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	security_type VARCHAR(32) NOT NULL, 
	asset_class VARCHAR(32) NOT NULL, 
	sector VARCHAR(64), 
	region VARCHAR(48) NOT NULL, 
	currency VARCHAR(8) NOT NULL, 
	last_price FLOAT NOT NULL, 
	previous_close FLOAT NOT NULL, 
	dividend_yield FLOAT NOT NULL, 
	expense_ratio FLOAT, 
	beta FLOAT NOT NULL, 
	annualised_volatility FLOAT NOT NULL, 
	esg_score FLOAT, 
	is_municipal BOOLEAN NOT NULL, 
	substantially_identical_to VARCHAR(24), 
	price_as_of TIMESTAMP WITH TIME ZONE, 
	price_status VARCHAR(24) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_securities_asset_class ON securities (asset_class);

CREATE INDEX ix_securities_class ON securities (asset_class, sector);

CREATE UNIQUE INDEX ix_securities_symbol ON securities (symbol);

CREATE TABLE users (
	email VARCHAR(255) NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	role VARCHAR(48) NOT NULL, 
	title VARCHAR(120), 
	phone VARCHAR(40), 
	avatar_initials VARCHAR(4), 
	password_hash VARCHAR(255), 
	supabase_user_id VARCHAR(64), 
	is_active BOOLEAN NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	demo_label VARCHAR(64), 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	timezone VARCHAR(64) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE INDEX ix_users_role ON users (role);

CREATE INDEX ix_users_role_active ON users (role, is_active);

CREATE INDEX ix_users_supabase_user_id ON users (supabase_user_id);

CREATE TABLE advisor_teams (
	name VARCHAR(120) NOT NULL, 
	region VARCHAR(80), 
	lead_advisor_id VARCHAR(36), 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	FOREIGN KEY(lead_advisor_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE households (
	name VARCHAR(160) NOT NULL, 
	segment VARCHAR(48) NOT NULL, 
	primary_advisor_id VARCHAR(36), 
	risk_profile VARCHAR(32) NOT NULL, 
	since DATE, 
	city VARCHAR(80), 
	state VARCHAR(40), 
	notes TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(primary_advisor_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_households_name ON households (name);

CREATE INDEX ix_households_primary_advisor_id ON households (primary_advisor_id);

CREATE TABLE role_permissions (
	role_id VARCHAR(36) NOT NULL, 
	permission_id VARCHAR(36) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_role_permission UNIQUE (role_id, permission_id), 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE CASCADE, 
	FOREIGN KEY(permission_id) REFERENCES permissions (id) ON DELETE CASCADE
);

CREATE INDEX ix_role_permissions_permission_id ON role_permissions (permission_id);

CREATE INDEX ix_role_permissions_role_id ON role_permissions (role_id);

CREATE TABLE saved_views (
	user_id VARCHAR(36) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	query VARCHAR(255) NOT NULL, 
	categories JSON NOT NULL, 
	is_pinned BOOLEAN NOT NULL, 
	use_count INTEGER NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_saved_views_user_id ON saved_views (user_id);

CREATE TABLE search_history (
	user_id VARCHAR(36) NOT NULL, 
	query VARCHAR(255) NOT NULL, 
	result_count INTEGER NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_search_history_user_id ON search_history (user_id);

CREATE INDEX ix_search_user_time ON search_history (user_id, created_at);

CREATE TABLE sponsors (
	name VARCHAR(160) NOT NULL, 
	industry VARCHAR(80) NOT NULL, 
	employee_count INTEGER NOT NULL, 
	ein_masked VARCHAR(24), 
	location VARCHAR(120), 
	relationship_since DATE, 
	primary_contact_id VARCHAR(36), 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name), 
	FOREIGN KEY(primary_contact_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE TABLE advisor_assignments (
	advisor_id VARCHAR(36) NOT NULL, 
	household_id VARCHAR(36) NOT NULL, 
	team_id VARCHAR(36), 
	role_on_account VARCHAR(48) NOT NULL, 
	is_primary BOOLEAN NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_advisor_household_role UNIQUE (advisor_id, household_id, role_on_account), 
	FOREIGN KEY(advisor_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(team_id) REFERENCES advisor_teams (id) ON DELETE SET NULL
);

CREATE INDEX ix_advisor_assignments_advisor_id ON advisor_assignments (advisor_id);

CREATE INDEX ix_assignment_household ON advisor_assignments (household_id);

CREATE TABLE audit_events (
	actor_id VARCHAR(36), 
	actor_name VARCHAR(160) NOT NULL, 
	actor_role VARCHAR(48), 
	household_id VARCHAR(36), 
	action VARCHAR(64) NOT NULL, 
	entity_type VARCHAR(48) NOT NULL, 
	entity_id VARCHAR(36), 
	entity_label VARCHAR(200), 
	status VARCHAR(24) NOT NULL, 
	summary TEXT, 
	before_state JSON, 
	after_state JSON, 
	ip_address VARCHAR(64), 
	user_agent VARCHAR(255), 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE SET NULL
);

CREATE INDEX ix_audit_actor_time ON audit_events (actor_id, created_at);

CREATE INDEX ix_audit_entity ON audit_events (entity_type, entity_id);

CREATE INDEX ix_audit_events_action ON audit_events (action);

CREATE INDEX ix_audit_events_actor_id ON audit_events (actor_id);

CREATE INDEX ix_audit_events_entity_type ON audit_events (entity_type);

CREATE INDEX ix_audit_events_household_id ON audit_events (household_id);

CREATE INDEX ix_audit_household_time ON audit_events (household_id, created_at);

CREATE TABLE clients (
	user_id VARCHAR(36), 
	household_id VARCHAR(36) NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	birth_date DATE, 
	retirement_age INTEGER NOT NULL, 
	filing_status VARCHAR(32) NOT NULL, 
	marginal_tax_rate FLOAT NOT NULL, 
	ltcg_tax_rate FLOAT NOT NULL, 
	state_tax_rate FLOAT NOT NULL, 
	annual_income FLOAT NOT NULL, 
	annual_savings FLOAT NOT NULL, 
	risk_tolerance VARCHAR(32) NOT NULL, 
	status VARCHAR(32) NOT NULL, 
	segment VARCHAR(48) NOT NULL, 
	onboarded_on DATE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_clients_full_name ON clients (full_name);

CREATE INDEX ix_clients_household_id ON clients (household_id);

CREATE UNIQUE INDEX ix_clients_user_id ON clients (user_id);

CREATE TABLE estate_plans (
	household_id VARCHAR(36) NOT NULL, 
	plan_name VARCHAR(160) NOT NULL, 
	document_type VARCHAR(48) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	executed_on DATE, 
	last_reviewed_on DATE, 
	next_review_due DATE, 
	attorney VARCHAR(120), 
	jurisdiction VARCHAR(80), 
	executor VARCHAR(120), 
	notes TEXT, 
	estimated_estate_value FLOAT NOT NULL, 
	projected_estate_tax FLOAT NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_estate_plans_household_id ON estate_plans (household_id);

CREATE TABLE gifts (
	household_id VARCHAR(36) NOT NULL, 
	charity_id VARCHAR(36), 
	security_id VARCHAR(36), 
	recipient VARCHAR(160) NOT NULL, 
	gift_type VARCHAR(48) NOT NULL, 
	amount FLOAT NOT NULL, 
	cost_basis FLOAT, 
	gifted_on DATE NOT NULL, 
	tax_year INTEGER NOT NULL, 
	uses_annual_exclusion BOOLEAN NOT NULL, 
	is_qcd BOOLEAN NOT NULL, 
	deduction_amount FLOAT NOT NULL, 
	capital_gain_avoided FLOAT NOT NULL, 
	notes TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(charity_id) REFERENCES charities (id) ON DELETE SET NULL, 
	FOREIGN KEY(security_id) REFERENCES securities (id) ON DELETE SET NULL
);

CREATE INDEX ix_gifts_household_id ON gifts (household_id);

CREATE INDEX ix_gifts_tax_year ON gifts (tax_year);

CREATE TABLE giving_plans (
	household_id VARCHAR(36) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	tax_year INTEGER NOT NULL, 
	target_amount FLOAT NOT NULL, 
	committed_amount FLOAT NOT NULL, 
	mission_focus VARCHAR(120) NOT NULL, 
	strategy VARCHAR(120) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	review_date DATE, 
	last_updated_at TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_giving_plans_household_id ON giving_plans (household_id);

CREATE TABLE household_members (
	household_id VARCHAR(36) NOT NULL, 
	full_name VARCHAR(160) NOT NULL, 
	relationship_type VARCHAR(48) NOT NULL, 
	birth_date DATE, 
	is_dependent BOOLEAN NOT NULL, 
	email VARCHAR(255), 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_household_members_household_id ON household_members (household_id);

CREATE TABLE meetings (
	household_id VARCHAR(36) NOT NULL, 
	advisor_id VARCHAR(36), 
	title VARCHAR(200) NOT NULL, 
	meeting_type VARCHAR(48) NOT NULL, 
	starts_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	duration_minutes INTEGER NOT NULL, 
	location VARCHAR(120) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	agenda JSON NOT NULL, 
	notes TEXT, 
	summary TEXT, 
	attendees JSON NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(advisor_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_meetings_advisor_id ON meetings (advisor_id);

CREATE INDEX ix_meetings_household_id ON meetings (household_id);

CREATE INDEX ix_meetings_household_start ON meetings (household_id, starts_at);

CREATE INDEX ix_meetings_starts_at ON meetings (starts_at);

CREATE TABLE message_threads (
	household_id VARCHAR(36) NOT NULL, 
	subject VARCHAR(200) NOT NULL, 
	topic VARCHAR(48) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	last_message_at TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_message_threads_household_id ON message_threads (household_id);

CREATE INDEX ix_message_threads_last_message_at ON message_threads (last_message_at);

CREATE TABLE plans (
	sponsor_id VARCHAR(36) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	plan_number VARCHAR(16) NOT NULL, 
	plan_type VARCHAR(32) NOT NULL, 
	plan_year_end DATE NOT NULL, 
	total_assets FLOAT NOT NULL, 
	eligible_employees INTEGER NOT NULL, 
	participating_employees INTEGER NOT NULL, 
	average_deferral_rate FLOAT NOT NULL, 
	employer_match_formula VARCHAR(160) NOT NULL, 
	vesting_schedule VARCHAR(96) NOT NULL, 
	auto_enrollment BOOLEAN NOT NULL, 
	auto_enrollment_rate FLOAT NOT NULL, 
	auto_escalation BOOLEAN NOT NULL, 
	auto_escalation_cap FLOAT NOT NULL, 
	loans_allowed BOOLEAN NOT NULL, 
	hardship_allowed BOOLEAN NOT NULL, 
	recordkeeper VARCHAR(120) NOT NULL, 
	advisor_id VARCHAR(36), 
	plan_health_score FLOAT NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sponsor_id) REFERENCES sponsors (id) ON DELETE CASCADE, 
	FOREIGN KEY(advisor_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX ix_plans_sponsor_id ON plans (sponsor_id);

CREATE TABLE portfolios (
	household_id VARCHAR(36) NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	strategy VARCHAR(64) NOT NULL, 
	benchmark_id VARCHAR(36), 
	inception_date DATE, 
	management_fee_bps INTEGER NOT NULL, 
	as_of TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(benchmark_id) REFERENCES benchmarks (id) ON DELETE SET NULL
);

CREATE INDEX ix_portfolios_household_id ON portfolios (household_id);

CREATE TABLE powers_of_attorney (
	household_id VARCHAR(36) NOT NULL, 
	poa_type VARCHAR(48) NOT NULL, 
	principal VARCHAR(120) NOT NULL, 
	agent VARCHAR(120) NOT NULL, 
	successor_agent VARCHAR(120), 
	executed_on DATE, 
	status VARCHAR(24) NOT NULL, 
	notes TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_powers_of_attorney_household_id ON powers_of_attorney (household_id);

CREATE TABLE tasks (
	title VARCHAR(200) NOT NULL, 
	description TEXT, 
	assignee_id VARCHAR(36), 
	household_id VARCHAR(36), 
	category VARCHAR(48) NOT NULL, 
	priority VARCHAR(16) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	due_date DATE, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	sla_days INTEGER, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(assignee_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE
);

CREATE INDEX ix_tasks_assignee_id ON tasks (assignee_id);

CREATE INDEX ix_tasks_assignee_status ON tasks (assignee_id, status);

CREATE INDEX ix_tasks_household_id ON tasks (household_id);

CREATE TABLE accounts (
	household_id VARCHAR(36) NOT NULL, 
	client_id VARCHAR(36), 
	custodian_id VARCHAR(36), 
	name VARCHAR(160) NOT NULL, 
	account_number_masked VARCHAR(32) NOT NULL, 
	account_type VARCHAR(32) NOT NULL, 
	account_subtype VARCHAR(48), 
	tax_treatment VARCHAR(32) NOT NULL, 
	registration VARCHAR(64) NOT NULL, 
	currency VARCHAR(8) NOT NULL, 
	balance FLOAT NOT NULL, 
	cash_balance FLOAT NOT NULL, 
	is_liability BOOLEAN NOT NULL, 
	interest_rate FLOAT, 
	minimum_payment FLOAT, 
	status VARCHAR(24) NOT NULL, 
	is_external BOOLEAN NOT NULL, 
	opened_on DATE, 
	last_synced_at TIMESTAMP WITH TIME ZONE, 
	data_source VARCHAR(48) NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(client_id) REFERENCES clients (id) ON DELETE SET NULL, 
	FOREIGN KEY(custodian_id) REFERENCES custodians (id) ON DELETE SET NULL
);

CREATE INDEX ix_accounts_account_type ON accounts (account_type);

CREATE INDEX ix_accounts_client ON accounts (client_id);

CREATE INDEX ix_accounts_household_id ON accounts (household_id);

CREATE INDEX ix_accounts_household_type ON accounts (household_id, account_type);

CREATE TABLE action_items (
	meeting_id VARCHAR(36), 
	household_id VARCHAR(36), 
	thread_id VARCHAR(36), 
	title VARCHAR(200) NOT NULL, 
	owner VARCHAR(120) NOT NULL, 
	due_date DATE, 
	status VARCHAR(24) NOT NULL, 
	notes TEXT, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(meeting_id) REFERENCES meetings (id) ON DELETE CASCADE, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(thread_id) REFERENCES message_threads (id) ON DELETE SET NULL
);

CREATE INDEX ix_action_items_household_id ON action_items (household_id);

CREATE INDEX ix_action_items_meeting_id ON action_items (meeting_id);

CREATE TABLE alerts (
	user_id VARCHAR(36), 
	household_id VARCHAR(36), 
	plan_id VARCHAR(36), 
	category VARCHAR(48) NOT NULL, 
	severity VARCHAR(16) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	entity_type VARCHAR(48), 
	entity_id VARCHAR(36), 
	action_url VARCHAR(200), 
	due_date DATE, 
	read_at TIMESTAMP WITH TIME ZONE, 
	dismissed_at TIMESTAMP WITH TIME ZONE, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(household_id) REFERENCES households (id) ON DELETE CASCADE, 
	FOREIGN KEY(plan_id) REFERENCES plans (id) ON DELETE CASCADE
);

CREATE INDEX ix_alerts_category ON alerts (category);

CREATE INDEX ix_alerts_household_category ON alerts (household_id, category);

CREATE INDEX ix_alerts_user_id ON alerts (user_id);

CREATE INDEX ix_alerts_user_read ON alerts (user_id, read_at);

CREATE TABLE allocations (
	portfolio_id VARCHAR(36) NOT NULL, 
	asset_class VARCHAR(32) NOT NULL, 
	kind VARCHAR(24) NOT NULL, 
	target_weight FLOAT NOT NULL, 
	min_weight FLOAT NOT NULL, 
	max_weight FLOAT NOT NULL, 
	tolerance_band FLOAT NOT NULL, 
	id VARCHAR(36) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_allocation_target UNIQUE (portfolio_id, asset_class, kind), 
	FOREIGN KEY(portfolio_id) REFERENCES portfolios (id) ON DELETE CASCADE
);

CREATE INDEX ix_allocations_portfolio_id ON allocations (portfolio_id);

CREATE TABLE approvals (
	household_id VARCHAR(36), 
	plan_id VARCHAR(36), 
	entity_type VARCHAR(48) NOT NULL, 
	entity_id VARCHAR(36), 
	title VARCHAR(200) NOT NULL, 
	summary TEXT, 
	status VARCHAR(24) NOT NULL, 
	priority VARCHAR(16) NOT NULL, 
	requested_by_id VARCHAR(36), 
	assigned_to_id VARCHAR(36), 
	decided_by_id VARCHAR(36), 
	required_role VARCHAR(48) NOT NULL, 
	submitted_at TIMESTAMP WITH TIME ZONE, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	completed_at TIMESTAMP WITH TIME ZONE, 
