	FOREIGN KEY(account_id) REFERENCES accounts (id) ON DELETE CASCADE, 
	FOREIGN KEY(trust_id) REFERENCES trusts (id) ON DELETE SET NULL, 
	FOREIGN KEY(approval_id) REFERENCES approvals (id) ON DELETE SET NULL
);

